def solve_magic(index, seq, fixed):
    if index == len(seq):
        return is_magic(seq)
    if index in fixed:
        seq[index] = fixed[index]
        if solve_magic(index + 1, seq, fixed):
            return True
        seq[index] = -1  # reset
        return False
